/** Flags that several commands share, so each one has one meaning. */
export const dirFlag = {
    dir: {
        type: "string",
        default: ".",
        value: "<path>",
        kind: "path",
        description: "Project root, or a folder of agent projects.",
    },
};
export const jsonFlag = {
    json: {
        type: "boolean",
        description: 'Print JSON on stdout, errors included ({"error":{code,message,hint}}).',
    },
};
export const teamFlag = {
    team: {
        type: "string",
        value: "<id>",
        kind: "teamId",
        description: "Cursor team id. Defaults to the signed-in account's team.",
    },
};
export const apiKeyFlag = {
    "api-key": {
        type: "string",
        value: "<key>",
        description: "Cursor API key. Defaults to CURSOR_API_KEY, CURSOR_API_KEY_FILE, CURSOR_SERVICE_ACCOUNT_KEY, then the `agent-sdk login` key.",
    },
};
export const slugFlag = {
    slug: {
        type: "string",
        value: "<slug>",
        kind: "slug",
        description: "Agent slug. Defaults to the --dir folder name.",
    },
};
/**
 * Use the hosted deployment. Commands that take it also spread
 * {@link urlFlag}, {@link slugFlag}, {@link teamFlag}, and {@link apiKeyFlag}.
 */
export const prodFlag = {
    prod: {
        type: "boolean",
        description: "Use the team's hosted deployment (needs `agent-sdk login`). Not with --url.",
    },
};
export const noWaitFlag = {
    "no-wait": {
        type: "boolean",
        description: "Return when the request is accepted. Do not wait for the result.",
    },
};
export const timeoutFlag = {
    "timeout-ms": {
        type: "string",
        value: "<n>",
        description: "Stop a turn that runs longer than this many milliseconds.",
    },
};
export const noStreamFlag = {
    "no-stream": { type: "boolean", description: "Do not print live progress on stderr." },
};
export const stateRootFlag = {
    "state-root": {
        type: "string",
        value: "<path>",
        // Not an outputPath: the folder belongs outside the repository, often
        // as a relative ../ path, and hosting passes its own.
        kind: "path",
        description: "Durable state folder (default <dir>/.agent-serve). Put it outside any repository whose rules must not reach the agent.",
    },
};
/** `--session`, plus the older `--session-id` spelling that scripts still pass. */
export const sessionFlags = {
    session: {
        type: "string",
        value: "<id>",
        kind: "sessionId",
        description: "Existing session id.",
    },
    "session-id": {
        type: "string",
        hidden: true,
        kind: "sessionId",
        description: "Older spelling of --session.",
    },
};
/** Text is the default output, so `--text` is a hidden no-op for old scripts. */
export const textFlag = {
    text: { type: "boolean", hidden: true, description: "No effect: text is the default." },
};
/** Paging for list commands. `--json` prints `{ items, nextPageToken }`. */
export const limitFlags = {
    limit: {
        type: "string",
        value: "<n>",
        integer: { min: 1, max: 100 },
        description: "Print at most this many items (default 20).",
    },
    "page-token": {
        type: "string",
        value: "<token>",
        description: "Start at this page: the nextPageToken of the previous page.",
    },
};
/** A field mask for `--json` output. */
export const fieldsFlag = {
    fields: {
        type: "string",
        value: "<a,b.c>",
        description: "With --json: print only these comma-separated fields (dot paths).",
    },
};
export const printFlag = {
    print: { type: "boolean", description: "Print the URL only. Do not open a browser." },
};
/**
 * `--prod` on a command that runs only locally or against --url. It stays
 * accepted so the command can print the hosted alternative (exit 2).
 */
export const prodRejectedFlag = {
    prod: {
        type: "boolean",
        hidden: true,
        description: "Not supported. Prints the hosted alternative and exits 2.",
    },
};
export const urlFlag = {
    url: {
        type: "string",
        value: "<baseUrl>",
        kind: "url",
        description: "Base URL of a running agent. Skips the local host.",
    },
};
export const bearerTokenFlag = {
    "bearer-token": {
        type: "string",
        value: "<token>",
        description: "Send this bearer token to --url.",
    },
};
/**
 * One meaning everywhere: change nothing and show what the command would
 * do. A hosted command stops at its first request that changes state and
 * prints that request.
 */
export const dryRunFlag = {
    "dry-run": {
        type: "boolean",
        description: "Change nothing. Print what the command would do, or the request it would send.",
    },
};
/** Skip the confirmation prompt of a command that cannot be undone. */
export const yesFlag = {
    yes: { type: "boolean", description: "Confirm without a prompt (needed without a TTY)." },
};
/**
 * `--print` meant "write nothing" on `install-skills`, `mcp install`, and
 * `slack manifest` before `--dry-run` did. Old scripts still pass it.
 */
export const printAliasFlag = {
    print: { type: "boolean", hidden: true, description: "Older spelling of --dry-run." },
};
